+/**
+ * Sanitizes SVG content to prevent XSS attacks
+ * Removes script tags, event handlers, and javascript: URLs
+ */
+function sanitizeSvg(content) {
+  let sanitized = content;
+
+  // Remove script tags
+  sanitized = sanitized.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
+
+  // Remove on* event handlers (onclick, onload, onerror, etc.)
+  sanitized = sanitized.replace(/\s+on\w+\s*=\s*(['"])[^'"]*\1/gi, '');
+  sanitized = sanitized.replace(/\s+on\w+\s*=\s*[^\s>]+/gi, '');
+
+  // Remove javascript: URLs
+  sanitized = sanitized.replace(/javascript:/gi, '');
+
+  // Remove data: URLs (can be used for data exfiltration)
+  sanitized = sanitized.replace(/data:/gi, '');
+
+  // Remove SVG-specific elements that can execute code
+  const dangerousElements = ['foreignObject', 'animate', 'set'];
+  dangerousElements.forEach(elem => {
+    const regex = new RegExp(`<${elem}[\\s\\S]*?</${elem}>`, 'gi');
+    sanitized = sanitized.replace(regex, '');
+  });
+
+  return sanitized;
+}
+
+module.exports = { sanitizeSvg };
