+/**
+ * Redacts sensitive information from strings
+ */
+
+/**
+ * Redacts a Telegram bot token from a URL
+ * Bot tokens appear in URLs like: https://api.telegram.org/bot<TOKEN>/method
+ * @param {string} url - The URL to redact
+ * @returns {string} - The URL with the bot token redacted
+ */
+function redactBotToken(url) {
+	if (!url || typeof url !== 'string') {
+		return url;
+	}
+	// Match pattern: /bot<anything up to next slash or end of string>
+	return url.replace(/\/bot[^/]*/gi, '/bot[redacted]');
+}
+
+module.exports = { redactBotToken };
