+/**
+ * Escapes a string for use in HTML
+ * @param {string} str The string to escape
+ * @return {string} The escaped string
+ */
+export function escapeHtml(str) {
+	if (typeof str !== 'string') {
+		return str;
+	}
+
+	return str
+		.replace(/&/g, '&amp;')
+		.replace(/</g, '&lt;')
+		.replace(/>/g, '&gt;')
+		.replace(/"/g, '&quot;')
+		.replace(/'/g, '&#039;');
+}
