+++ b/src/utils/validate-redirect-url.ts
@@ -0,0 +1,21 @@
+/**
+ * Validates that a redirect URL points to an allowed domain
+ * @param url The URL to validate
+ * @param allowedDomains List of allowed domains
+ * @returns The validated URL if it passes
+ * @throws Error if URL is not allowed
+ */
+export function validateRedirectUrl(url: string, allowedDomains: string[]): string {
+	const parsedUrl = new URL(url);
+
+	// Allow relative URLs
+	if (!parsedUrl.hostname) {
+		return url;
+	}
+
+	const isAllowed = allowedDomains.some((domain) => {
+		return parsedUrl.hostname === domain || parsedUrl.hostname.endsWith(`.${domain}`);
+	});
+
+	if (!isAllowed) {
+		throw new Error(`Redirect to ${parsedUrl.hostname} is not allowed`);
+	}
+
+	return url;
+}

