+ *
+ * @param {Object} request - The request object
+ * @param {Object} response - The response object containing Vary header
+ * @returns {Object} - The cache key object
+ */
+export function generateVaryKey(request, response) {
+  const varyHeader = response?.headers?.['vary'];
+  
+  if (!varyHeader) {
+    return null;
+  }
+
+  const varyHeaders = varyHeader.split(',').map(h => h.trim().toLowerCase());
+  const keyParts = {};
+
+  for (const header of varyHeaders) {
+    if (request.headers && request.headers[header]) {
+      keyParts[header] = request.headers[header];
+    }
+  }
+
+  if (Object.keys(keyParts).length === 0) {
+    return null;
+  }
+
+  return generateKey({ ...request, _varyKey: keyParts });
+}
