+const INTERNAL_HOSTS = [
+  'localhost',
+  '127.0.0.1',
+  '::1',
+  '0.0.0.0',
+  'metadata.google.internal',
+  'metadata.google',
+];
+
+const INTERNAL_IP_RANGES = [
+  /^10\./,
+  /^172\.(1[6-9]|2[0-9]|3[0-1])\./,
+  /^192\.168\./,
+  /^127\./,
+  /^169\.254\./,
+  /^fc00:/i,
+  /^fe80:/i,
+  /^::1$/,
+  /^::ffff:/,
+];
+
+export function isInternalUrl(host: string): boolean {
+  const normalizedHost = host.toLowerCase();
+
+  // Check exact matches for known internal hosts
+  if (INTERNAL_HOSTS.some(h => normalizedHost === h || normalizedHost.endsWith('.' + h))) {
+    return true;
+  }
+
+  // Check IP ranges
+  if (INTERNAL_IP_RANGES.some(regex => regex.test(normalizedHost))) {
+    return true;
+  }
+
+  return false;
+}
+
+export function isCloudMetadataEndpoint(url: string): boolean {
+  const metadataEndpoints = [
+    '169.254.169.254',  // AWS, GCP, Azure
+    'metadata.google.internal',
+  ];
+  
+  return metadataEndpoints.some(endpoint => url.includes(endpoint));
+}

