@@ -0,0 +1,27 @@
+/**
+ * Password utility functions for bcryptjs compatibility
+ * bcryptjs truncates passwords at 72 bytes, so we need to validate/truncate
+ * to prevent authentication bypass and performance issues.
+ */
+
+// Maximum password length for bcryptjs (72 bytes)
+export const MAX_PASSWORD_LENGTH = 72;
+
+/**
+ * Validates that a password does not exceed the maximum length
+ * @throws Error if password exceeds 72 characters
+ */
+export const validatePassword = (password: string): void => {
+  if (password && password.length > MAX_PASSWORD_LENGTH) {
+    throw new Error(
+      `Password exceeds maximum length of ${MAX_PASSWORD_LENGTH} characters. ` +
+      `Please use a shorter password.`
+    );
+  }
+};
+
+/**
+ * Truncates a password to the maximum length for bcryptjs compatibility
+ * Used during authentication to handle passwords set before this fix
+ */
+export const truncatePassword = (password: string): string => {
+  if (password && password.length > MAX_PASSWORD_LENGTH) {
+    return password.substring(0, MAX_PASSWORD_LENGTH);
+  }
+  return password;
+};
