+/**
+ * Validates that a URL is same-origin (relative URL or same domain)
+ * This prevents open redirect attacks (CWE-601)
+ * 
+ * @param url The URL to validate
+ * @returns true if the URL is same-origin, false otherwise
+ */
+export function isSameOrigin(url: string): boolean {
+  // Allow relative URLs (start with /, but not //)
+  if (url.startsWith('/') && !url.startsWith('//')) {
+    return true;
+  }
+  
+  // Block dangerous schemes
+  if (url.startsWith('javascript:') || url.startsWith('data:') || url.startsWith('mailto:')) {
+    return false;
+  }
+  
+  // For absolute URLs, check if they match the current origin
+  try {
+    const urlObj = new URL(url, window.location.origin);
+    return urlObj.origin === window.location.origin;
+  } catch {
+    return false;
+  }
+}

