+// Copyright (c) 2015-present Mattermost, Inc. All Rights Reserved.
+// See LICENSE.txt for license information.
+
+import {ipcMain, desktopCapturer, BrowserWindow} from 'electron';
+
+import {isDev} from './common';
+
+let hasUserConsent = false;
+
+export function initScreenCapture() {
+    ipcMain.handle('get-sources', async (event, options) => {
+        // Security: Require user consent before allowing screen capture
+        if (!hasUserConsent) {
+            throw new Error('Screen capture requires user consent. Please enable screen capture permission first.');
+        }
+
+        // Validate that the request comes from a legitimate window
+        const validSources = ['window', 'screen'];
+        if (options && options.types && !options.types.some((t: string) => validSources.includes(t))) {
+            throw new Error('Invalid source types requested for screen capture.');
+        }
+
+        return desktopCapturer.getSources(options);
+    });
+
+    ipcMain.on('set-screen-capture-consent', (event, consent) => {
+        if (typeof consent !== 'boolean') {
+            return;
+        }
+        hasUserConsent = consent;
+    });
+}
+
+export function resetScreenCaptureConsent() {
+    hasUserConsent = false;
+}
+
+export function getScreenCaptureConsent(): boolean {
+    return hasUserConsent;
+}
