+/**
+ * Check if a URL resolves to a blocked/internal IP address
+ * @param {string} url - The URL to check
+ * @returns {Promise<boolean>} - Returns true if URL is safe, false if blocked
+ */
+async function isUrlSafe(url) {
+    try {
+        const urlObj = new URL(url);
+        
+        // Only allow http/https protocols
+        if (!['http:', 'https:'].includes(urlObj.protocol)) {
+            return false;
+        }
+        
+        const hostname = urlObj.hostname;
+        
+        // Check if hostname is a private IP
+        if (isPrivateIp(hostname)) {
+            return false;
+        }
+        
+        // Resolve hostname and check all IPs
+        const dns = require('dns');
+        const { promisify } = require('util');
+        const resolve4 = promisify(dns.resolve4);
+        
+        try {
+            const ips = await resolve4(hostname);
+            for (const ip of ips) {
+                if (isPrivateIp(ip)) {
+                    return false;
+                }
+            }
+        } catch (e) {
+            // If DNS resolution fails, allow the URL but let it fail naturally
+        }
+        
+        return true;
+    } catch (e) {
+        return false;
+    }
+}
+
+module.exports = {
+    isUrlSafe,
+    blocklist,
+};
