diff --git a/source/core/database/encoder.js b/source/core/database/encoder.js
new file mode 100644
index 0000000..1234567
--- /dev/null
+++ b/source/core/database/encoder.js
@@ -0,0 +1,30 @@
+/**
+ * 中国蚁剑::数据库配置输出编码模块
+ * 用于防止XSS攻击
+ */
+'use strict';
+
+/**
+ * HTML转义编码 - 防止XSS
+ * @param {string} str 需要转义的字符串
+ * @return {string} 转义后的字符串
+ */
+function htmlEncode(str) {
+  if (typeof str !== 'string') {
+    return str;
+  }
+  return str
+    .replace(/&/g, '&amp;')
+    .replace(/</g, '&lt;')
+    .replace(/>/g, '&gt;')
+    .replace(/"/g, '&quot;')
+    .replace(/'/g, '&#x27;')
+    .replace(/\//g, '&#x2F;');
+}
+
+/**
+ * JavaScript字符串转义 - 防止JS注入
+ * @param {string} str 需要转义的字符串
+ * @return {string} 转义后的字符串
+ */
+function jsEncode(str) {
+  if (typeof str !== 'string') {
+    return str;
+  }
+  return str
+    .replace(/\\/g, '\\\\')
+    .replace(/'/g, "\\'")
+    .replace(/"/g, '\\"')
+    .replace(/</g, '\\u003C')
+    .replace(/>/g, '\\u003E');
+}
+
+module.exports = {
+  htmlEncode,
+  jsEncode
+};
