+/**
+ * Sanitizes a file system path by removing potentially dangerous
+ * Unicode control/format characters that could be used for prompt injection.
+ * @param {string} path - The path to sanitize
+ * @returns {string} The sanitized path
+ */
+function sanitizePath(path) {
+  if (!path || typeof path !== 'string') {
+    return '';
+  }
+  
+  return path
+    // Remove Unicode control characters (C0 controls)
+    .replace(/[\u0000-\u001F\u007F-\u009F]/g, '')
+    // Remove line/paragraph separators
+    .replace(/[\u2028\u2029]/g, '')
+    // Remove zero-width characters
+    .replace(/[\u200B-\u200D\uFEFF]/g, '');
+}
+
+module.exports = { sanitizePath };
