+/**
+ * Sanitizes input for AcroForm text fields to prevent PDF injection attacks.
+ * Escapes "/" characters which could be used to inject arbitrary PDF objects.
+ *
+ * @param {string} input - The input string to sanitize.
+ * @returns {string} - The sanitized string with "/" characters escaped.
+ */
+function sanitizeAcroFormText(input) {
+  if (typeof input !== 'string') {
+    return input;
+  }
+  // Escape forward slashes to prevent PDF object injection
+  // PDF objects start with "/" so we escape it to "\/"
+  return input.replace(/\//g, '\\/');
+}
+
+export { sanitizeAcroFormText };

