@@ -0,0 +1,25 @@
+import { isIp, isPrivate, isLoopback } from "net"
+
+/**
+ * Check if the given host is a private/internal address
+ * that can be safely proxied to
+ */
+export function isPrivateIp(host: string): boolean {
+  // Check if it's a valid IP first
+  if (isIp(host)) {
+    return isPrivate(host) || isLoopback(host)
+  }
+
+  // Allow localhost aliases
+  if (host === "localhost" || host === "0.0.0.0") {
+    return true
+  }
+
+  // If it's not a valid IP and not localhost, treat as external
+  return false
+}

