+var crypto = require('crypto');
+
+var csrf = module.exports = {};
+
+var SECRET_KEY = 'whistle-csrf-secret-' + Math.random();
+
+csrf.generate = function(req) {
+  var sessionId = req.sessionID || req.ip || 'default';
+  var timestamp = Date.now();
+  var data = sessionId + ':' + timestamp;
+  var hmac = crypto.createHmac('sha256', SECRET_KEY);
+  hmac.update(data);
+  var token = hmac.digest('hex') + ':' + timestamp;
+  return token;
+};
+
+csrf.validate = function(req) {
+  var token = req.headers['x-csrf-token'] || 
+              req.body._csrf || 
+              req.query._csrf;
+  
+  if (!token) {
+    return false;
+  }
+  
+  var parts = token.split(':');
+  if (parts.length !== 2) {
+    return false;
+  }
+  
+  var sessionId = req.sessionID || req.ip || 'default';
+  var expectedToken = csrf.generate(req);
+  
+  return token === expectedToken;
+};

