+import { NextRequest } from 'next/server';
+import { OpenAI } from 'openai';
+import { requestWithTimeout } from '@/app/api/chat/openai/utils';
+import { checkAuth } from '@/app/api/chat/openai/auth';
+import { isEndpointAllowed } from '@/features/PromptStore/ConfigProvider';
+
+export const runtime = 'edge';
+
+export async function POST(req: NextRequest) {
+  const authResult = checkAuth(req);
+  if (!authResult.isValid) {
+    return authResult.error;
+  }
+
+  const { apiKey, endpoint } = authResult;
+
+  // SSRF Protection: Validate endpoint URL
+  if (!isEndpointAllowed(endpoint)) {
+    return new Response(JSON.stringify({
+      error: {
+        message: 'Invalid endpoint URL: requests to internal or private network addresses are not allowed',
+        type: 'invalid_request_error',
+      }
+    }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' }
+    });
+  }
+
+  let body;
+  try {
+    body = await req.json();
+  } catch {
+    return new Response(JSON.stringify({
+      error: {
+        message: 'Invalid JSON in request body',
+        type: 'invalid_request_error',
+      }
+    }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' }
+    });
+  }
+
+  const { messages, ...params } = body;
+
+  const client = new OpenAI({
+    apiKey,
+    baseURL: endpoint,
+    httpAgent: undefined,
+  });
+
+  try {
+    const response = await requestWithTimeout(
+      client.chat.completions.create({
+        messages,
+        ...params,
+      }),
+      60000
+    );
+
+    return new Response(response.toReadableStream(), {
+      headers: {
+        'Content-Type': 'text/event-stream',
+      },
+    });
+  } catch (err: any) {
+    return new Response(JSON.stringify({
+      error: {
+        message: err.message || 'An error occurred',
+        type: 'invalid_request_error',
+      }
+    }), {
+      status: 500,
+      headers: { 'Content-Type': 'application/json' }
+    });
+  }
+}

