+import { Transform } from 'stream';
+
+/** Escapes HTML special characters to prevent XSS attacks */
+export function escapeHtml(unsafe: string): string {
+  return unsafe
+    .replace(/&/g, '&amp;')
+    .replace(/</g, '&lt;')
+    .replace(/>/g, '&gt;')
+    .replace(/"/g, '&quot;')
+    .replace(/'/g, '&#x27;');
+}
+
+/** Transform stream that escapes HTML in the response body */
+export class EscapeHtmlTransform extends Transform {
+  constructor() {
+    super({ writableObjectMode: true });
+  }
+
+  _transform(chunk: any, encoding: string, callback: () => void) {
+    const escaped = typeof chunk === 'string' ? escapeHtml(chunk) : chunk;
+    this.push(escaped);
+    callback();
+  }
+}

